from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak
from pptx import Presentation
from pptx.dml.color import RGBColor
from pptx.util import Inches, Pt

ROOT=Path(__file__).resolve().parents[1]; docs=ROOT/'docs'

def build_pdf():
    path=docs/'architecture.pdf'; doc=SimpleDocTemplate(str(path),pagesize=A4,rightMargin=15*mm,leftMargin=15*mm,topMargin=12*mm,bottomMargin=12*mm)
    styles=getSampleStyleSheet(); styles.add(ParagraphStyle(name='Small',parent=styles['BodyText'],fontSize=8.2,leading=11,textColor=colors.HexColor('#53677e'))); styles.add(ParagraphStyle(name='Head',parent=styles['Heading1'],fontSize=18,leading=21,textColor=colors.HexColor('#122137'),spaceAfter=5)); styles.add(ParagraphStyle(name='Sub',parent=styles['Heading2'],fontSize=11,leading=14,textColor=colors.HexColor('#237c61'),spaceBefore=7,spaceAfter=3)); styles.add(ParagraphStyle(name='Code2',parent=styles['Code'],fontSize=7.3,leading=9,textColor=colors.HexColor('#d6efe5'),backColor=colors.HexColor('#122035'),borderPadding=7))
    story=[Paragraph('LOGFLUX architecture',styles['Head']),Paragraph('Universal Log Pre-processing Framework · Cybersecurity Innovation Challenge',styles['Small']),Spacer(1,4*mm),Paragraph('Purpose and flow',styles['Sub']),Paragraph('LOGFLUX receives perimeter telemetry through TCP/UDP Syslog, optional TLS Syslog, file upload, and an authenticated HTTP API. A bounded receiver writes the original bytes to immutable evidence before parsing. Each event carries a UUID, SHA-256, source identity, transport, framing, and receipt time. Unknown and drifted events remain queryable while the review workflow creates approved, signed parsers.',styles['Small']),Spacer(1,3*mm),Paragraph('Firewall / router / IDS / other devices<br/>↓ TCP · UDP · TLS Syslog · file · HTTP<br/>Bounded receiver → immutable raw evidence → approved parser → LOGFLUX event<br/>↓ unknown or drifted → Drain3 structure → local model proposal → deterministic checks<br/>→ replay + WASM sandbox → human approval → signed plugin → replay revisions<br/>raw manifests → Merkle batches → 2-of-3 signed local witnesses',styles['Code2']),Spacer(1,3*mm)]
    data=[['Layer','Working behavior'],['Capture','Bounded TCP, UDP, optional TLS Syslog; upload and HTTP input; durable raw commit before processing.'],['Preserve','Byte-exact immutable raw bytes, hash, source, receipt time, framing, and provenance.'],['Understand','Format adapters; Drain3 templates; local semantic proposal; deterministic type and meaning checks.'],['Control','WASM projection with no host imports, memory/fuel limits; replay, mutation checks, human approval.'],['Standardize','Versioned LOGFLUX network event; unmapped source fields; ECS/JSONL/CSV export; quality status.'],['Investigate','Merkle proofs, signed witness checkpoints, drift recovery, relationships, timeline, alerts, and cases.']]
    t=Table([[Paragraph(x,styles['Small']) for x in row] for row in data],colWidths=[32*mm,148*mm]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e8f4ef')),('TEXTCOLOR',(0,0),(-1,0),colors.HexColor('#1f6e54')),('GRID',(0,0),(-1,-1),.3,colors.HexColor('#dfe7ed')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)])); story.append(t); story.append(PageBreak()); story += [Paragraph('Security and operating boundaries',styles['Sub']),Paragraph('Parser projections run in Wasmtime with no host imports, a 64 KiB memory ceiling, and a fuel limit. Model output is untrusted data and cannot deploy or approve itself. The registry pins trusted public keys; Ed25519 signatures protect bundle integrity and origin. Raw and revision records are append-only, and signed audit records form a hash chain.',styles['Small']),Spacer(1,3*mm),Paragraph('Integrity uses domain-separated Merkle leaf and parent hashes. A 2-of-3 local witness quorum signs ordered checkpoints. The default witnesses share one host, so the quorum detects inconsistency but does not provide independent custody or Byzantine consensus. UDP loss before receipt cannot be recovered.',styles['Small']),Spacer(1,3*mm),Paragraph('Operations and scaling',styles['Sub']),Paragraph('The UI labels live, lab, and replay traffic. Drift compares a source fingerprint to its baseline and routes changes to review. “Self-healing” means assisted correction and approved replay. The HTTP outbox retries at least once with an idempotency key. The SQLite-WAL single-node store is a demonstrator; production scale requires partitioned storage, horizontally scaled workers, a durable broker, object storage, and independently administered witness nodes.',styles['Small']),Spacer(1,3*mm),Paragraph('Acceptance evidence',styles['Sub']),Paragraph('The included test suite covers raw-byte and malformed-input handling, format adapters, drift quarantine, replay revisions, signed bundles, Merkle proofs, witness outage/catch-up, WASM resource limits, concurrent ingestion, API auth, exports, and local security headers. A real-firewall connection and billion-event capacity require deployment-specific verification and must be shown as measured evidence during evaluation.',styles['Small'])]; doc.build(story); return path

def add_text(slide, text, x, y, w, h, size=18, color='17263A', bold=False):
    box=slide.shapes.add_textbox(Inches(x),Inches(y),Inches(w),Inches(h)); tf=box.text_frame; tf.clear(); p=tf.paragraphs[0]; p.text=text; p.font.name='Aptos'; p.font.size=Pt(size); p.font.bold=bold; p.font.color.rgb=RGBColor.from_string(color); return box
def build_pptx():
    prs=Presentation(); prs.slide_width=Inches(13.333); prs.slide_height=Inches(7.5)
    slides=[('LOGFLUX','Universal Log Pre-processing Framework\nCybersecurity Innovation Challenge','Preserve every received event. Standardize its meaning. Keep evidence ready for investigation.'),('The problem','One perimeter, many dialects','Firewalls, routers, IDS/IPS, VPNs and network software emit Syslog, JSON, CEF, LEEF, XML, CSV and vendor formats. Source-specific parsers slow down analytics and create gaps when formats change.'),('The working architecture','Capture first · normalize second','Bounded TCP / UDP / TLS Syslog and file/HTTP input → immutable raw evidence → format detection → approved parser → versioned LOGFLUX event → dashboard, ECS export, SIEM outbox and investigation. Unknown or drifted events go to a review queue.'),('Controlled adaptation','A parser cannot change production by itself','Drain3 discovers structure. A local model may propose mappings. Deterministic validation, replay, mutation tests and semantic assertions produce a report. A reviewer approves a signed WASM bundle containing the parser projection, SBOM and test vectors. Retained events replay as new revisions; originals never change.'),('Proof and demonstration','Make the claim measurable','Show a real device or isolated lab source; compare raw and normalized views; introduce a format change; approve and replay; verify the raw hash, Merkle proof and witness quorum; follow relationships into a timeline and case. Report throughput and storage from measured runs. The included prototype runs offline and labels replay traffic explicitly.')]
    for i,(title,body,sub) in enumerate(slides):
        slide=prs.slides.add_slide(prs.slide_layouts[6]); bg=slide.background.fill; bg.solid(); bg.fore_color.rgb=RGBColor(244,246,249)
        slide.shapes.add_shape(1,Inches(0),Inches(0),Inches(.28),Inches(7.5)).fill.solid(); slide.shapes[-1].fill.fore_color.rgb=RGBColor(180,242,217); slide.shapes[-1].line.fill.background()
        add_text(slide,f'{i+1:02d} / 05',.7,.5,1.5,.3,11,'5A7188',True); add_text(slide,title,.7,1.15,11.8,.7,28,'122137',True); add_text(slide,sub,.7,2.05,11.4,.75,17,'277C61',False); add_text(slide,body,.7,3.15,11.5,1.8,19,'40566D',False)
        add_text(slide,'LOGFLUX  ·  Evidence-preserving telemetry',.7,6.85,6,.25,10,'8292A4',False)
    prs.save(docs/'presentation.pptx'); return docs/'presentation.pptx'

if __name__=='__main__': print(build_pdf()); print(build_pptx())
